export function romanToInt(roman: string): number {
  const value: Record<string, number> = {I:1,V:5,X:10,L:50,C:100,D:500,M:1000}; let total = 0; for (let i = 0; i < roman.length; i++) { const current = value[roman[i]], next = value[roman[i+1]] ?? 0; total += current < next ? -current : current; } return total;
}
